pragma solidity ^0.8.0;

import {AaveTokenV3} from '../../src/AaveTokenV3.sol';
import {DelegationMode} from '../../src/DelegationAwareBalance.sol';

contract AaveTokenV3Harness is AaveTokenV3 {
  function getBalance(address user) public view returns (uint104) {
    return _balances[user].balance;
  }

  function getDelegatedPropositionBalance(address user) public view returns (uint72) {
    return _balances[user].delegatedPropositionBalance;
  }

  function getDelegatedVotingBalance(address user) public view returns (uint72) {
    return _balances[user].delegatedVotingBalance;
  }

  function getDelegatingProposition(address user) public view returns (bool) {
    uint8 state = uint8(_balances[user].delegationMode);
    return
      state == uint8(DelegationMode.PROPOSITION_DELEGATED) ||
      state == uint8(DelegationMode.FULL_POWER_DELEGATED);
  }

  function getDelegatingVoting(address user) public view returns (bool) {
    uint8 state = uint8(_balances[user].delegationMode);
    return
      state == uint8(DelegationMode.VOTING_DELEGATED) ||
      state == uint8(DelegationMode.FULL_POWER_DELEGATED);
  }

  function getVotingDelegatee(address user) public view returns (address) {
    return _votingDelegatee[user];
  }

  function getPropositionDelegatee(address user) public view returns (address) {
    return _propositionDelegatee[user];
  }

  function getDelegationMode(address user) public view returns (DelegationMode) {
    return _balances[user].delegationMode;
  }
}

pragma solidity ^0.8.0;

import {BaseAaveTokenV2} from './BaseAaveTokenV2.sol';
import {BaseDelegation} from './BaseDelegation.sol';

contract AaveTokenV3 is BaseAaveTokenV2, BaseDelegation {

  function initialize() external virtual initializer {}

  function _afterTokenTransfer(
    address from,
    address to,
    uint256 fromBalanceBefore,
    uint256 toBalanceBefore,
    uint256 amount
  ) internal override {
    _delegationChangeOnTransfer(from, to, fromBalanceBefore, toBalanceBefore, amount);
  }

  function _getDelegationState(address user)
    internal
    view
    override
    returns (DelegationState memory)
  {
    DelegationAwareBalance memory userState = _balances[user];
    return
      DelegationState({
        delegatedPropositionBalance: userState.delegatedPropositionBalance,
        delegatedVotingBalance: userState.delegatedVotingBalance,
        delegationMode: userState.delegationMode
      });
  }

  function _getBalance(address user) internal view override returns (uint256) {
    return _balances[user].balance;
  }

  function _setDelegationState(address user, DelegationState memory delegationState)
    internal
    override
  {
    DelegationAwareBalance storage userState = _balances[user];
    userState.delegatedPropositionBalance = delegationState.delegatedPropositionBalance;
    userState.delegatedVotingBalance = delegationState.delegatedVotingBalance;
    userState.delegationMode = delegationState.delegationMode;
  }

  function _incrementNonces(address user) internal override returns (uint256) {
    unchecked {
      return _nonces[user]++;
    }
  }

  function _getDomainSeparator() internal view override returns (bytes32) {
    return DOMAIN_SEPARATOR();
  }
}

