pragma solidity ^0.8.0;

import {StakedAaveV3} from '../munged/src/contracts/StakedAaveV3.sol';
import {IERC20} from 'openzeppelin-contracts/contracts/token/ERC20/IERC20.sol';
import {ECDSA} from 'openzeppelin-contracts/contracts/utils/cryptography/ECDSA.sol';

import {DelegationMode} from 'aave-token-v3/DelegationAwareBalance.sol';
import {BaseDelegation} from 'aave-token-v3/BaseDelegation.sol';

contract StakedAaveV3Harness is StakedAaveV3 {
    constructor(IERC20 stakedToken, IERC20 rewardToken, uint256 unstakeWindow, address rewardsVault,
                address emissionManager, uint128 distributionDuration)
        StakedAaveV3(stakedToken, rewardToken, unstakeWindow, rewardsVault,
                    emissionManager, distributionDuration) {}
    function cooldownAmount(address user) public view returns (uint216) {
        return stakersCooldowns[user].amount;
    }
    function cooldownTimestamp(address user) public view returns (uint40) {
        return stakersCooldowns[user].timestamp;
    }
    function getAssetEmissionPerSecond(address token) public view returns (uint128) {
        return assets[token].emissionPerSecond;
    }
    function getAssetLastUpdateTimestamp(address token) public view returns (uint128) {
        return assets[token].lastUpdateTimestamp;
    }
    function getAssetGlobalIndex(address token) public view returns (uint256) {
        return assets[token].index;
    }
    function getUserPersonalIndex(address token, address user) public view returns (uint256) {
        return assets[token].users[user];
    }

    function _getExchangeRateWrapper(uint256 totalAssets, uint256 totalShares) public pure returns (uint216) {
        return _getExchangeRate(totalAssets, totalShares);
    }
    function getBalance(address user) public view returns (uint104) {
        return _balances[user].balance;
    }
    function getDelegatedPropositionBalance(address user) public view returns (uint72) {
        return _balances[user].delegatedPropositionBalance;
    }
    function getDelegatedVotingBalance(address user) public view returns (uint72) {
        return _balances[user].delegatedVotingBalance;
    }
    function getDelegatingProposition(address user) public view returns (bool) {
        return
            _balances[user].delegationMode == DelegationMode.PROPOSITION_DELEGATED ||
            _balances[user].delegationMode == DelegationMode.FULL_POWER_DELEGATED;
    }
    function getDelegatingVoting(address user) public view returns (bool) {
        return
            _balances[user].delegationMode == DelegationMode.VOTING_DELEGATED ||
            _balances[user].delegationMode == DelegationMode.FULL_POWER_DELEGATED;
    }
    function getVotingDelegatee(address user) public view returns (address) {
        return _votingDelegatee[user];
    }
    function getPropositionDelegatee(address user) public view returns (address) {
        return _propositionDelegatee[user];
    }
    function getDelegationMode(address user) public view returns (DelegationMode) {
        return _balances[user].delegationMode;
    }

    function ecrecoverWrapper(
                              bytes32 hash,
                              uint8 v,
                              bytes32 r,
                              bytes32 s
    ) public pure returns (address) {
        return ecrecover(hash, v, r, s);
    }

    function computeMetaDelegateHash(address delegator, address delegatee, uint256 deadline, uint256 nonce)
        public view returns (bytes32) {
        bytes32 digest =
            ECDSA.toTypedDataHash(
                                  _getDomainSeparator(),
                                  keccak256(abi.encode(DELEGATE_TYPEHASH, delegator, delegatee, nonce, deadline))
            );
        return digest;
    }

    function computeMetaDelegateByTypeHash(
                                           address delegator,
                                           address delegatee,
                                           GovernancePowerType delegationType,
                                           uint256 deadline,
                                           uint256 nonce
    ) public view returns (bytes32) {
        bytes32 digest = ECDSA.toTypedDataHash(
                                               _getDomainSeparator(),
                                               keccak256(
                                                         abi.encode(
                                                                    DELEGATE_BY_TYPE_TYPEHASH,
                                                                    delegator,
                                                                    delegatee,
                                                                    delegationType,
                                                                    nonce,
                                                                    deadline
                                                         )
                                               )
        );

        return digest;
    }

    function getPowerCurrent_BaseDelegation(address user, GovernancePowerType delegationType)
        public view virtual returns (uint256) {
        return BaseDelegation.getPowerCurrent(user,delegationType);
    }

    function getNonce(address user) public view returns (uint256) {
        return _nonces[user];
    }
}

pragma solidity ^0.8.0;

import {IERC20} from 'openzeppelin-contracts/contracts/token/ERC20/IERC20.sol';
import {DistributionTypes} from '../lib/DistributionTypes.sol';
import {StakedTokenV3} from './StakedTokenV3.sol';
import {IGhoVariableDebtTokenTransferHook} from '../interfaces/IGhoVariableDebtTokenTransferHook.sol';
import {SafeCast} from '../lib/SafeCast.sol';
import {IStakedAaveV3} from '../interfaces/IStakedAaveV3.sol';

contract StakedAaveV3 is StakedTokenV3, IStakedAaveV3 {
  using SafeCast for uint256;

  uint256[1] private ______DEPRECATED_FROM_STK_AAVE_V3;
  IGhoVariableDebtTokenTransferHook public ghoDebtToken;

  function REVISION() public pure virtual override returns (uint256) {
    return 6;
  }

  constructor(
    IERC20 stakedToken,
    IERC20 rewardToken,
    uint256 unstakeWindow,
    address rewardsVault,
    address emissionManager,
    uint128 distributionDuration
  )
    StakedTokenV3(
      stakedToken,
      rewardToken,
      unstakeWindow,
      rewardsVault,
      emissionManager,
      distributionDuration
    )
  {
    lastInitializedRevision = REVISION();
  }


  function initialize() external override initializer {}
  function claimRewardsAndStake(
    address to,
    uint256 amount
  ) external override returns (uint256) {
    return _claimRewardsAndStakeOnBehalf(msg.sender, to, amount);
  }
  function claimRewardsAndStakeOnBehalf(
    address from,
    address to,
    uint256 amount
  ) external override onlyClaimHelper returns (uint256) {
    return _claimRewardsAndStakeOnBehalf(from, to, amount);
  }


  function _afterTokenTransfer(
    address from,
    address to,
    uint256 fromBalanceBefore,
    uint256 toBalanceBefore,
    uint256 amount
  ) internal override {
    super._afterTokenTransfer(
      from,
      to,
      fromBalanceBefore,
      toBalanceBefore,
      amount
    );

    address cachedGhoDebtToken = address(ghoDebtToken);
    if (cachedGhoDebtToken != address(0)) {
      _updateDiscountDistribution(
        cachedGhoDebtToken,
        from,
        to,
        fromBalanceBefore,
        toBalanceBefore,
        amount
      );
    }
  }
  function _updateDiscountDistribution(
    address cachedGhoDebtToken,
    address from,
    address to,
    uint256 fromBalanceBefore,
    uint256 toBalanceBefore,
    uint256 amount
  ) internal {
    bytes4 selector = IGhoVariableDebtTokenTransferHook
      .updateDiscountDistribution
      .selector;
    uint256 gasLimit = 220_000;
    assembly {
      let ptr := mload(0x40)
      mstore(ptr, selector)
      mstore(add(ptr, 0x04), from)
      mstore(add(ptr, 0x24), to)
      mstore(add(ptr, 0x44), fromBalanceBefore)
      mstore(add(ptr, 0x64), toBalanceBefore)
      mstore(add(ptr, 0x84), amount)

      let gasLeft := gas()
      if iszero(call(gasLimit, cachedGhoDebtToken, 0, ptr, 0xA4, 0, 0)) {
        if lt(div(mul(gasLeft, 63), 64), gasLimit) {
          returndatacopy(ptr, 0, returndatasize())
          revert(ptr, returndatasize())
        }
      }
    }
  }
}

specs.clean_source:
//     This is a specification file for the verification of general ERC20 properties.
//     This file was adapted from AaveTokenV3.sol smart contract to STK-3.0 smart contract.
//     This file is run by the command line:
//           certoraRun --send_only certora/scripts/token-v3-erc20.sh
//     It uses the harness file: certora/harness/StakedAaveV3Harness.sol
import "base.spec";



//     @Rule
//     @Description:
//         Verify that there is no fee on transferFrom() (like potentially on USDT)
//     @Formula:
//         {
//             balances[bob] = y
//             allowance(alice, msg.sender) >= amount
//         }
//         <
//             transferFrom(alice, bob, amount)
//         >
//         {
//             balances[bob] = y + amount
//         }
//     @Notes:
//     @Link:
rule noFeeOnTransferFrom(address alice, address bob, uint256 amount) {
    env e;
    calldataarg args;
    require alice != bob;
    require allowance(alice, e.msg.sender) >= amount;
    mathint balanceBefore = balanceOf(bob);

    transferFrom(e, alice, bob, amount);

    mathint balanceAfter = balanceOf(bob);
    assert balanceAfter == balanceBefore + amount;
}

//     @Rule
//     @Description:
//         Verify that there is no fee on transfer() (like potentially on USDT)
//     @Formula:
//         {
//             balances[bob] = y
//             balances[msg.sender] >= amount
//         }
//         <
//             transfer(bob, amount)
//         >
//         {
//             balances[bob] = y + amount
//         }
//     @Notes:
//     @Link:
rule noFeeOnTransfer(address bob, uint256 amount) {
    env e;
    calldataarg args;
    require bob != e.msg.sender;
    mathint balanceSenderBefore = balanceOf(e.msg.sender);
    mathint balanceBefore = balanceOf(bob);

    transfer(e, bob, amount);

    mathint balanceAfter = balanceOf(bob);
    mathint balanceSenderAfter = balanceOf(e.msg.sender);
    assert balanceAfter == balanceBefore + amount;
}

invariant userIndex_LEQ_index(address user, address asset)
    getUserAssetData(user,asset) <= getAssetGlobalIndex(asset);

//     @Rule
//     @Description:
//         Token transfer works correctly. Balances are updated if not reverted.
//     @Formula:
//         {
//             balanceFromBefore = balanceOf(msg.sender)
//             balanceToBefore = balanceOf(to)
//         }
//         <
//             transfer(to, amount)
//         >
//         {
//             balanceOf(to) = balanceToBefore + amount &&
//             balanceOf(msg.sender) = balanceFromBefore - amount
//         }
//     @Notes:
//         This rule fails on tokens with a blacklist function, like USDC and USDT.
//         The prover finds a counterexample of a reverted transfer to a blacklisted address or a transfer in a paused state.
//     @Link:
rule transferCorrect(address to, uint256 amount) {
    env e;
    require e.msg.value == 0 && e.msg.sender != 0;
    uint256 fromBalanceBefore = balanceOf(e.msg.sender);
    uint256 toBalanceBefore = balanceOf(to);
    require fromBalanceBefore + toBalanceBefore < AAVE_MAX_SUPPLY() / 100;

    // proven elsewhere
    address v_delegateTo = getVotingDelegatee(to);
    mathint dvbTo = getDelegatedVotingBalance(v_delegateTo);
    require dvbTo >= balanceOf(to) / FACTOR() && 
        dvbTo < SCALED_MAX_SUPPLY() - amount / FACTOR();
    address p_delegateTo = getPropositionDelegatee(to);
    mathint pvbTo = getDelegatedPropositionBalance(p_delegateTo);
    require pvbTo >= balanceOf(to) / FACTOR() && 
        pvbTo < SCALED_MAX_SUPPLY() - amount / FACTOR();

    // proven elsewhere
    address v_delegateFrom = getVotingDelegatee(e.msg.sender);
    address p_delegateFrom = getPropositionDelegatee(e.msg.sender);
    mathint dvbFrom = getDelegatedVotingBalance(v_delegateFrom);
    mathint pvbFrom = getDelegatedPropositionBalance(p_delegateFrom);
    require dvbFrom >= balanceOf(e.msg.sender) / FACTOR();
    require pvbFrom >= balanceOf(e.msg.sender) / FACTOR();

    require validDelegationMode(e.msg.sender) && validDelegationMode(to);
    require ! ( (getDelegatingVoting(to) && v_delegateTo == to) ||
                (getDelegatingProposition(to) && p_delegateTo == to));
    require validDelegationMode(p_delegateFrom) && validDelegationMode(p_delegateTo);
    require validDelegationMode(v_delegateFrom) && validDelegationMode(v_delegateTo);

    // to not overcomplicate the constraints on dvbTo and dvbFrom
    require v_delegateFrom != v_delegateTo && p_delegateFrom != p_delegateTo;

    transfer(e, to, amount);

    if (e.msg.sender == to) {
        assert balanceOf(e.msg.sender) == fromBalanceBefore;
    } else {
        assert to_mathint(balanceOf(e.msg.sender)) == fromBalanceBefore - amount;
        assert to_mathint(balanceOf(to)) == toBalanceBefore + amount;
    }
}

//     @Rule
//     @Description:
//         Test that transferFrom works correctly. Balances are updated if not reverted.
//         If reverted, it means the transfer amount was too high, or the recipient is 0
//     @Formula:
//         {
//             balanceFromBefore = balanceOf(from)
//             balanceToBefore = balanceOf(to)
//         }
//         <
//             transferFrom(from, to, amount)
//         >
//         {
//             lastreverted => to = 0 || amount > balanceOf(from)
//             !lastreverted => balanceOf(to) = balanceToBefore + amount &&
//                             balanceOf(from) = balanceFromBefore - amount
//         }
//     @Notes:
//         This rule fails on tokens with a blacklist and or pause function, like USDC and USDT.
//         The prover finds a counterexample of a reverted transfer to a blacklisted address or a transfer in a paused state.
//     @Link:

rule transferFromCorrect(address from, address to, uint256 amount) {
    env e;
    require e.msg.value == 0;
    uint256 fromBalanceBefore = balanceOf(from);
    uint256 toBalanceBefore = balanceOf(to);
    uint256 allowanceBefore = allowance(from, e.msg.sender);
    require fromBalanceBefore + toBalanceBefore < to_mathint(AAVE_MAX_SUPPLY());

    transferFrom(e, from, to, amount);

    assert from != to =>
        to_mathint(balanceOf(from)) == fromBalanceBefore - amount &&
        to_mathint(balanceOf(to)) == toBalanceBefore + amount &&
        (to_mathint(allowance(from, e.msg.sender)) == allowanceBefore - amount ||
         allowance(from, e.msg.sender) == max_uint256);
}

//     @Rule
//     @Description:
//         Balance of address 0 is always 0
//     @Formula:
//         { balanceOf[0] = 0 }
//     @Notes:
//     @Link:
invariant ZeroAddressNoBalance()
    balanceOf(0) == 0;

//     @Rule
//     @Description:
//         Contract calls don't change token total supply.
//     @Formula:
//         {
//             supplyBefore = totalSupply()
//         }
//         < f(e, args)>
//         {
//             supplyAfter = totalSupply()
//             supplyBefore == supplyAfter
//         }
//     @Notes:
//         This rule should fail for any token that has functions that change totalSupply(), like mint() and burn().
//         It's still important to run the rule and see if it fails in functions that _aren't_ supposed to modify totalSupply()
//     @Link:
rule NoChangeTotalSupply(method f) {
    // require f.selector != sig:burn(uint256).selector && f.selector != sig:mint(address, uint256).selector;
    uint256 totalSupplyBefore = totalSupply();
    env e;
    calldataarg args;
    f(e, args);
    assert totalSupply() != totalSupplyBefore =>
        (is_redeem_method(f) || is_stake_method(f))
        ;
}

//  The two rules cover the same ground as NoChangeTotalSupply.
//  The split into two rules is in order to make the burn/mint features of a tested token even more obvious
//  Those rules are not relevant for STK-3.0 hence removed.
// rule noBurningTokens(method f) {
//     uint256 totalSupplyBefore = totalSupply();
//     env e;
//     calldataarg args;
//     f(e, args);
//     assert totalSupply() >= totalSupplyBefore;
// }
// rule noMintingTokens(method f) {
//     uint256 totalSupplyBefore = totalSupply();
//     env e;
//     calldataarg args;
//     f(e, args);
//     assert totalSupply() <= totalSupplyBefore;
// }

//     @Rule
//     @Description:
//         Allowance changes correctly as a result of calls to approve, transfer, increaseAllowance, decreaseAllowance
//     @Formula:
//         {
//             allowanceBefore = allowance(from, spender)
//         }
//         <
//             f(e, args)
//         >
//         {
//             f.selector = approve(spender, amount) => allowance(from, spender) = amount
//             f.selector = transferFrom(from, spender, amount) => allowance(from, spender) = allowanceBefore - amount
//             f.selector = decreaseAllowance(spender, delta) => allowance(from, spender) = allowanceBefore - delta
//             f.selector = increaseAllowance(spender, delta) => allowance(from, spender) = allowanceBefore + delta
//             generic f.selector => allowance(from, spender) == allowanceBefore
//         }
//     @Notes:
//         Some ERC20 tokens have functions like permit() that change allowance via a signature.
//         The rule will fail on such functions.
//     @Link:
rule ChangingAllowance(method f, address from, address spender) {
    uint256 allowanceBefore = allowance(from, spender);
    env e;
    if (f.selector == sig:approve(address, uint256).selector) {
        address spender_;
        uint256 amount;
        approve(e, spender_, amount);
        if (from == e.msg.sender && spender == spender_) {
            assert allowance(from, spender) == amount;
        } else {
            assert allowance(from, spender) == allowanceBefore;
        }
    } else if (f.selector == sig:transferFrom(address,address,uint256).selector) {
        address from_;
        address to;
        uint256 amount;
        transferFrom(e, from_, to, amount);
        mathint allowanceAfter = allowance(from, spender);
        if (from == from_ && spender == e.msg.sender) {
            assert from == to || allowanceBefore == max_uint256 || allowanceAfter == allowanceBefore - amount;
        } else {
            assert allowance(from, spender) == allowanceBefore;
        }
    } else if (f.selector == sig:decreaseAllowance(address, uint256).selector) {
        address spender_;
        uint256 amount;
        require amount <= allowanceBefore;
        decreaseAllowance(e, spender_, amount);
        if (from == e.msg.sender && spender == spender_) {
            assert to_mathint(allowance(from, spender)) == allowanceBefore - amount;
        } else {
            assert allowance(from, spender) == allowanceBefore;
        }
    } else if (f.selector == sig:increaseAllowance(address, uint256).selector) {
        address spender_;
        uint256 amount;
        require amount + allowanceBefore < max_uint256;
        increaseAllowance(e, spender_, amount);
        if (from == e.msg.sender && spender == spender_) {
            assert to_mathint(allowance(from, spender)) == allowanceBefore + amount;
        } else {
            assert allowance(from, spender) == allowanceBefore;
        }
    } 
    else
    {
        calldataarg args;
        f(e, args);
        assert allowance(from, spender) == allowanceBefore ||
            f.selector == sig:permit(address,address,uint256,uint256,uint8,bytes32,bytes32).selector;
    }
}

//     @Rule
//     @Description:
//         Transfer from a to b doesn't change the sum of their balances
//     @Formula:
//         {
//             balancesBefore = balanceOf(msg.sender) + balanceOf(b)
//         }
//         <
//             transfer(b, amount)
//         >
//         {
//             balancesBefore == balanceOf(msg.sender) + balanceOf(b)
//         }
//     @Notes:
//     @Link:
rule TransferSumOfFromAndToBalancesStaySame(address to, uint256 amount) {
    env e;
    mathint sum = balanceOf(e.msg.sender) + balanceOf(to);
    require sum < max_uint256;
    transfer(e, to, amount); 
    assert balanceOf(e.msg.sender) + balanceOf(to) == sum;
}

//     @Rule
//     @Description:
//         Transfer using transferFrom() from a to b doesn't change the sum of their balances
//     @Formula:
//         {
//             balancesBefore = balanceOf(a) + balanceOf(b)
//         }
//         <
//             transferFrom(a, b)
//         >
//         {
//             balancesBefore == balanceOf(a) + balanceOf(b)
//         }
//     @Notes:
//     @Link:
rule TransferFromSumOfFromAndToBalancesStaySame(address from, address to, uint256 amount) {
    env e;
    mathint sum = balanceOf(from) + balanceOf(to);
    require sum < max_uint256;
    transferFrom(e, from, to, amount); 
    assert balanceOf(from) + balanceOf(to) == sum;
}

//     @Rule
//     @Description:
//         Transfer from msg.sender to alice doesn't change the balance of other addresses
//     @Formula:
//         {
//             balanceBefore = balanceOf(bob)
//         }
//         <
//             transfer(alice, amount)
//         >
//         {
//             balanceOf(bob) == balanceBefore
//         }
//     @Notes:
//     @Link:
rule TransferDoesntChangeOtherBalance(address to, uint256 amount, address other) {
    env e;
    require other != e.msg.sender;
    require other != to && other != currentContract;
    uint256 balanceBefore = balanceOf(other);
    transfer(e, to, amount); 
    assert balanceBefore == balanceOf(other);
}

//     @Rule
//     @Description:
//         Transfer from alice to bob using transferFrom doesn't change the balance of other addresses
//     @Formula:
//         {
//             balanceBefore = balanceOf(charlie)
//         }
//         <
//             transferFrom(alice, bob, amount)
//         >
//         {
//             balanceOf(charlie) = balanceBefore
//         }
//     @Notes:
//     @Link:
rule TransferFromDoesntChangeOtherBalance(address from, address to, uint256 amount, address other) {
    env e;
    require other != from;
    require other != to;
    uint256 balanceBefore = balanceOf(other);
    transferFrom(e, from, to, amount); 
    assert balanceBefore == balanceOf(other);
}

//     @Rule
//     @Description:
//         Balance of an address, who is not a sender or a recipient in transfer functions, doesn't decrease
//         as a result of contract calls
//     @Formula:
//         {
//             balanceBefore = balanceOf(charlie)
//         }
//         <
//             f(e, args)
//         >
//         {
//             f.selector != transfer && f.selector != transferFrom => balanceOf(charlie) == balanceBefore
//         }
//     @Notes:
//         USDC token has functions like transferWithAuthorization that use a signed message for allowance.
//         FTT token has a burnFrom that lets an approved spender to burn owner's token.
//         Certora prover finds these counterexamples to this rule.
//         In general, the rule will fail on all functions other than transfer/transferFrom that change a balance of an address.
//     @Link:
rule OtherBalanceOnlyGoesUp(address other, method f) {
    env e;
    require other != currentContract;
    uint256 balanceBefore = balanceOf(other);
    address from; address to; uint256 amount;

    if (f.selector == sig:transferFrom(address, address, uint256).selector) {
        require(other != from);
        require balanceOf(from) + balanceBefore < max_uint256;
        transferFrom(e, from, to, amount);
    } else if (f.selector == sig:transfer(address, uint256).selector) {
        require other != e.msg.sender;
        require balanceOf(e.msg.sender) + balanceBefore < max_uint256;
        calldataarg args;
        f(e, args);
    } else if (f.selector == sig:redeemOnBehalf(address, address, uint256).selector) {
        require(other != from);
        require balanceOf(from) + balanceBefore < max_uint256;
        redeemOnBehalf(e, from, to, amount);
    } else if (f.selector == sig:claimRewardsAndRedeemOnBehalf(address, address, uint256, uint256).selector) {
        uint256 claimAmount; uint256 redeemAmount;
        require(other != from);
        require balanceOf(from) + balanceBefore < max_uint256;
        claimRewardsAndRedeemOnBehalf(e, from, to, claimAmount, redeemAmount);
    } else {
        require other != e.msg.sender;
        calldataarg args;
        f(e, args);
    }

    assert balanceOf(other) >= balanceBefore;
}

rule noRebasing(method f, address alice) {
    env e;
    calldataarg args;

    require !is_transfer_method_func(f)
        && !is_stake_method(f) && !is_redeem_method(f)
        ;

    uint256 balanceBefore = balanceOf(alice);
    f(e, args);
    uint256 balanceAfter = balanceOf(alice);
    assert balanceBefore == balanceAfter;
}

